import {STAGES,demo,normalize,summary,visible,csv,localDate,isOpen} from './model.js';
const $=s=>document.querySelector(s),key='avytrix-partner-desk-v1';let rows=[],editing=null,stage='all',query='',sort='next',timer,storageError=false;
try{const saved=localStorage.getItem(key);rows=saved===null?demo():normalize(JSON.parse(saved));}catch{rows=demo();storageError=true;}
const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n);
const compact=n=>new Intl.NumberFormat('vi-VN',{notation:'compact',maximumFractionDigits:1}).format(n)+' ₫';
function toast(message){clearTimeout(timer);$('#toast').textContent=message;timer=setTimeout(()=>$('#toast').textContent='',4000);}
function save(){try{localStorage.setItem(key,JSON.stringify(rows));storageError=false;}catch{storageError=true;toast('Không thể lưu nháp. Hãy xuất CSV để giữ dữ liệu.');}render();}
function node(tag,className,text){const e=document.createElement(tag);if(className)e.className=className;if(text!==undefined)e.textContent=text;return e;}
function render(){const totals=summary(rows);for(const k of ['total','active','due'])$('#stat-'+k).textContent=totals[k];$('#stat-value').textContent=compact(totals.value);$('#stat-value').title=money(totals.value);$('#storage-status').textContent=storageError?'Không thể đọc hoặc lưu dữ liệu. Hãy xuất CSV trước khi đóng.':'Dữ liệu chỉ lưu trong trình duyệt của bạn.';
const filters=$('#filters'),focus=document.activeElement?.dataset.stage;filters.replaceChildren(...[['all','Tất cả'],...STAGES].map(([id,name])=>{const b=node('button','filter'+(stage===id?' active':''));b.type='button';b.dataset.stage=id;b.setAttribute('aria-pressed',String(stage===id));b.append(document.createTextNode(name),node('span','',id==='all'?rows.length:rows.filter(r=>r.stage===id).length));b.onclick=()=>{stage=id;render();};return b;}));if(focus!==undefined)filters.querySelector(`[data-stage="${focus}"]`)?.focus({preventScroll:true});
const list=visible(rows,{query,stage,sort});$('#result-count').textContent=list.length;$('#export').disabled=list.length===0;const container=$('#leads');container.replaceChildren();if(!list.length){const empty=node('div','empty');empty.append(node('strong','',rows.length?'Chưa tìm thấy cơ hội phù hợp':'Sẵn sàng cho kết nối đầu tiên?'),node('p','',rows.length?'Thử đổi từ khóa hoặc giai đoạn.':'Chọn “Thêm cơ hội” hoặc nạp lại dữ liệu mẫu.'));container.append(empty);return;}
for(const r of list){const b=node('button','lead');b.type='button';b.setAttribute('aria-label',`Chỉnh sửa ${r.company}: ${r.project}`);const identity=node('div','identity'),avatar=node('span','avatar',r.company.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase()),text=node('div');text.append(node('strong','',r.company),node('small','',r.project));identity.append(avatar,text);const badge=node('span','badge '+r.stage,STAGES.find(([s])=>s===r.stage)[1]),amount=node('span','amount',money(r.value)),next=node('div','next-action',r.next||'Chưa đặt bước tiếp theo');next.append(node('small',r.date&&r.date<=localDate()&&isOpen(r)?'due':'',r.date?new Date(r.date+'T12:00:00').toLocaleDateString('vi-VN')+(isOpen(r)&&r.date<=localDate()?' · Cần theo dõi':''):'Chưa đặt ngày'));b.append(identity,badge,amount,next,node('span','arrow','↗'));b.onclick=()=>open(r);container.append(b);}}
const dialog=$('#editor'),form=$('#lead-form');
function open(row){editing=row?.id||null;form.reset();$('#dialog-title').textContent=editing?'Chi tiết cơ hội':'Thêm cơ hội';$('#delete').hidden=!editing;for(const field of ['company','project','stage','value','next','date','notes'])form.elements[field].value=row?.[field]??(field==='stage'?'new':'');dialog.showModal();}
function close(){dialog.close();}
$('#new').onclick=()=>open();$('#close').onclick=close;$('#cancel').onclick=close;
form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));data.company=data.company.trim();data.project=data.project.trim();if(!data.company||!data.project){toast('Tên đối tác và dự án cần có nội dung.');return;}const record=normalize([{...data,id:editing||crypto.randomUUID()}])[0];if(editing)rows=rows.map(r=>r.id===editing?record:r);else rows.unshift(record);save();close();toast('Đã lưu cơ hội trên thiết bị.');};
$('#delete').onclick=()=>{if(confirm('Xóa cơ hội này khỏi thiết bị?')){rows=rows.filter(r=>r.id!==editing);save();close();toast('Đã xóa cơ hội.');}};
$('#search').oninput=e=>{query=e.target.value;render();};$('#sort').onchange=e=>{sort=e.target.value;render();};
function resetFilters(){query='';stage='all';sort='next';$('#search').value='';$('#sort').value='next';}
$('#load-demo').onclick=()=>{if(!confirm('Thay toàn bộ dữ liệu hiện tại bằng 6 cơ hội mẫu? Hãy xuất CSV trước nếu cần giữ lại.'))return;rows=demo();resetFilters();save();toast('Đã nạp dữ liệu minh họa.');};
$('#clear').onclick=()=>{if(!confirm('Xóa toàn bộ cơ hội trên thiết bị? Hãy xuất CSV trước nếu cần giữ lại.'))return;rows=[];resetFilters();save();toast('Đã xóa dữ liệu trên thiết bị.');};
$('#export').onclick=()=>{const data=visible(rows,{query,stage,sort}),url=URL.createObjectURL(new Blob([csv(data)],{type:'text/csv;charset=utf-8'})),a=node('a');a.href=url;a.download='rosieavytrix-partners-'+localDate()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Đã xuất ${data.length} cơ hội theo bộ lọc hiện tại.`);};
render();
